class Solution {
  public int findKthNumber(int n, int k) {
    long prefix = 1;
    k--;
    while (k > 0) {
      long count = count(prefix, n);
      if (count <= k) {
        prefix++;
        k -= count;
      } else {
        prefix *= 10;
        k--;
      }
    }
    return (int) prefix;
  }

  private long count(long prefix, int n) {
    long next = prefix + 1, total = 0;
    while (prefix <= n) {
      total += Math.min((long) n + 1, next) - prefix;
      prefix *= 10;
      next *= 10;
    }
    return total;
  }
}
